// 🦝 酒馆小狸 Live · 动态加载器
// 脚本本体托管 GitHub dist/（jsDelivr 三域备胎），版本指针在 Supabase ac_config.tanuki_script_ref
// @提交号 = 全新路径必回源，绕开 CDN 12h 缓存 = 发版秒切；指针失联退回 @main
(async function () {
  var ref = 'main';
  try {
    var c0 = (typeof AbortController !== 'undefined') ? new AbortController() : null;
    var t0 = c0 ? setTimeout(function () { c0.abort(); }, 6000) : null;
    var r0 = await fetch('https://hieylivlsdmyznviumht.supabase.co/rest/v1/ac_config?key=eq.tanuki_script_ref&select=value', { cache: 'no-store', signal: c0 ? c0.signal : undefined,
      headers: { 'apikey': 'sb_publishable_MH80Xnlm1oHli6UXwzRpNA_EsC1DnCO', 'Authorization': 'Bearer sb_publishable_MH80Xnlm1oHli6UXwzRpNA_EsC1DnCO' } });
    if (t0) clearTimeout(t0);
    if (r0.ok) {
      var j0 = await r0.json();
      var v0 = j0 && j0[0] && String(j0[0].value || '').trim();
      if (v0 && /^[w.-]{4,60}$/.test(v0)) ref = v0;   // 只认提交号/标签这种干净字符，防路径注入
    }
  } catch (e0) { console.warn('[TanukiLive loader] 版本指针拉取失败，退回 @main', e0); }
  var urls = ["testingcf.jsdelivr.net","fastly.jsdelivr.net","cdn.jsdelivr.net"].map(function (h) {
    return 'https://' + h + '/gh/fannnnnnn5822/tanuki-live@' + ref + '/dist/tanuki_live.js';
  });
  var code = null, lastErr = null;
  for (var i = 0; i < urls.length; i++) {
    try {
      // 被墙的域不是报错是挂死 → 12 秒闸刀，砍了换下一个源
      var ctrl = (typeof AbortController !== 'undefined') ? new AbortController() : null;
      var timer = ctrl ? setTimeout(function () { ctrl.abort(); }, 12000) : null;
      var resp = await fetch(urls[i], { cache: 'no-store', signal: ctrl ? ctrl.signal : undefined });
      if (timer) clearTimeout(timer);
      if (!resp.ok) throw new Error('HTTP ' + resp.status);
      code = await resp.text();
      if (!code || code.length < 1000) throw new Error('内容异常(' + (code ? code.length : 0) + ' chars)');
      console.log('[TanukiLive loader] via ' + urls[i].split('/')[2] + ' (' + code.length + ' chars)');
      break;
    } catch (e) { lastErr = e; code = null; console.warn('[TanukiLive loader] 源' + (i + 1) + '失败，换下一个', e); }
  }
  if (code == null) {
    try { toastr.error('小狸脚本加载失败（三个源都不通，多半是断网，刷新酒馆重试）：' + ((lastErr && lastErr.message) || lastErr), '🦝 酒馆小狸 Live'); } catch (e2) {}
    console.error('[TanukiLive loader] 全部源失败', lastErr);
    return;
  }
  try { eval(code); } catch (e3) {
    try { toastr.error('小狸脚本执行出错：' + ((e3 && e3.message) || e3), '🦝 酒馆小狸 Live'); } catch (e4) {}
    console.error('[TanukiLive loader] eval 失败', e3);
  }
})();
